    ('fe4edbed-be84-4b80-b5de-62ab3e4c88ef'::uuid, 'period_name', '4500 - 3000 BC', 'Undated', 'period-fix-2026-11-07d-s001-rollback:fe4edbed-be84-4b80-b5de-62ab3e4c88ef:period_name', 'rollback of period-fix-2026-11-07d-s001: period_name ''Undated'' restored on A Figa', '[{"source": "owner decision D138 (2026-11-07)", "url": "output/remediation/OWNER_DECISIONS_2026-10-08.md", "quote": "| D138 | (2026-11-07) The 60 year-stated-only sites of the D137 refine (year from the site''s own source, mostly the stored description) and the 2 scope-hold sites | **Write the 60** as the band of their stated year (owner: \"die 60 sites ja\"); **retire Caus Castle and Ayazini Kaya Church** as medieval / out of scope (owner: \"die 2 mittelalter deaktivieren\"), through the journalled scope-retire lane. |"}, {"source": "owner decision D137 (2026-11-07)", "url": "output/remediation/OWNER_DECISIONS_2026-10-08.md", "quote": "| D137 | D136 details after the spot checks | **Write all bands now** (owner: \"Egal, schreiben\"). A century/year the site''s own source states for the site wins over the epoch start (rec). A coarse word is read together with the site''s own monument type. |"}, {"source": "the year the site''s own source states (D138): -4300, unified_sites", "url": "unified_sites.description", "quote": "Radiocarbon dating places its primary occupation around 4300-4200 BCE."}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "the site''s own source states -4300: the band ''4500 - 3000 BC'', its edge -4500 (D137 year rule, D138)"}]'::jsonb),
    ('fe4edbed-be84-4b80-b5de-62ab3e4c88ef'::uuid, 'period_start', '-4500', NULL, 'period-fix-2026-11-07d-s001-rollback:fe4edbed-be84-4b80-b5de-62ab3e4c88ef:period_start', 'rollback of period-fix-2026-11-07d-s001: period_start None restored on A Figa', '[{"source": "owner decision D138 (2026-11-07)", "url": "output/remediation/OWNER_DECISIONS_2026-10-08.md", "quote": "| D138 | (2026-11-07) The 60 year-stated-only sites of the D137 refine (year from the site''s own source, mostly the stored description) and the 2 scope-hold sites | **Write the 60** as the band of their stated year (owner: \"die 60 sites ja\"); **retire Caus Castle and Ayazini Kaya Church** as medieval / out of scope (owner: \"die 2 mittelalter deaktivieren\"), through the journalled scope-retire lane. |"}, {"source": "owner decision D137 (2026-11-07)", "url": "output/remediation/OWNER_DECISIONS_2026-10-08.md", "quote": "| D137 | D136 details after the spot checks | **Write all bands now** (owner: \"Egal, schreiben\"). A century/year the site''s own source states for the site wins over the epoch start (rec). A coarse word is read together with the site''s own monument type. |"}, {"source": "the year the site''s own source states (D138): -4300, unified_sites", "url": "unified_sites.description", "quote": "Radiocarbon dating places its primary occupation around 4300-4200 BCE."}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "the site''s own source states -4300: the band ''4500 - 3000 BC'', its edge -4500 (D137 year rule, D138)"}]'::jsonb),
    ('ffb35fc7-24f7-4722-8036-e4173ac6d8e6'::uuid, 'period_name', '4500 - 3000 BC', 'Undated', 'period-fix-2026-11-07d-s001-rollback:ffb35fc7-24f7-4722-8036-e4173ac6d8e6:period_name', 'rollback of period-fix-2026-11-07d-s001: period_name ''Undated'' restored on Cardiccia', '[{"source": "owner decision D138 (2026-11-07)", "url": "output/remediation/OWNER_DECISIONS_2026-10-08.md", "quote": "| D138 | (2026-11-07) The 60 year-stated-only sites of the D137 refine (year from the site''s own source, mostly the stored description) and the 2 scope-hold sites | **Write the 60** as the band of their stated year (owner: \"die 60 sites ja\"); **retire Caus Castle and Ayazini Kaya Church** as medieval / out of scope (owner: \"die 2 mittelalter deaktivieren\"), through the journalled scope-retire lane. |"}, {"source": "owner decision D137 (2026-11-07)", "url": "output/remediation/OWNER_DECISIONS_2026-10-08.md", "quote": "| D137 | D136 details after the spot checks | **Write all bands now** (owner: \"Egal, schreiben\"). A century/year the site''s own source states for the site wins over the epoch start (rec). A coarse word is read together with the site''s own monument type. |"}, {"source": "the year the site''s own source states (D138): -4000, unified_sites", "url": "unified_sites.description", "quote": "Cardiccia is a megalithic dolmen (locally called a stazzona) in the commune of Sartene, southern Corsica, dating to the Late Neolithic or Early Bronze Age (c. 4000-2000 BC)."}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "the site''s own source states -4000: the band ''4500 - 3000 BC'', its edge -4500 (D137 year rule, D138)"}]'::jsonb),
    ('ffb35fc7-24f7-4722-8036-e4173ac6d8e6'::uuid, 'period_start', '-4500', NULL, 'period-fix-2026-11-07d-s001-rollback:ffb35fc7-24f7-4722-8036-e4173ac6d8e6:period_start', 'rollback of period-fix-2026-11-07d-s001: period_start None restored on Cardiccia', '[{"source": "owner decision D138 (2026-11-07)", "url": "output/remediation/OWNER_DECISIONS_2026-10-08.md", "quote": "| D138 | (2026-11-07) The 60 year-stated-only sites of the D137 refine (year from the site''s own source, mostly the stored description) and the 2 scope-hold sites | **Write the 60** as the band of their stated year (owner: \"die 60 sites ja\"); **retire Caus Castle and Ayazini Kaya Church** as medieval / out of scope (owner: \"die 2 mittelalter deaktivieren\"), through the journalled scope-retire lane. |"}, {"source": "owner decision D137 (2026-11-07)", "url": "output/remediation/OWNER_DECISIONS_2026-10-08.md", "quote": "| D137 | D136 details after the spot checks | **Write all bands now** (owner: \"Egal, schreiben\"). A century/year the site''s own source states for the site wins over the epoch start (rec). A coarse word is read together with the site''s own monument type. |"}, {"source": "the year the site''s own source states (D138): -4000, unified_sites", "url": "unified_sites.description", "quote": "Cardiccia is a megalithic dolmen (locally called a stazzona) in the commune of Sartene, southern Corsica, dating to the Late Neolithic or Early Bronze Age (c. 4000-2000 BC)."}, {"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "the site''s own source states -4000: the band ''4500 - 3000 BC'', its edge -4500 (D137 year rule, D138)"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 118;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _period_fix_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'D121 period correction: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _period_fix_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'period_start' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer
                WHEN 'period_name' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 100
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D121 period correction: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _period_fix_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'period_start' THEN u.period_start IS DISTINCT FROM p.old_value::integer
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D121 period correction: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row undos a value this lane owns (old value)
    SELECT count(*) INTO bad FROM _period_fix_plan p
     WHERE CASE p.column_name
                WHEN 'period_name' THEN p.old_value NOT IN ('< 4500 BC', '4500 - 3000 BC', '3000 - 1500 BC', '1500 - 500 BC', '500 BC - 1 AD', '1 - 500 AD', '500 - 1000 AD', '1000 - 1500 AD', '1500+ AD', 'Undated')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D121 period correction: % planned row(s) undo a value this lane does not own', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _period_fix_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'D121-D124/period-correction', '2026-11-07d_mechanical-period-fix-s001-rollback', r.change_key, 'authoritative', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'D121 period correction: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _period_fix_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'period_start' THEN u.period_start IS DISTINCT FROM p.new_value::integer
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D121 period correction: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _period_fix_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-11-07d_mechanical-period-fix-s001-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D121 period correction: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-11-07d_mechanical-period-fix-s001-rollback'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('period_start', 'period_name'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'D121 period correction: this run stamp journalled % row(s) outside unified_sites.(period_start, period_name)', bad;
    END IF;

    RAISE NOTICE 'D121 period correction: % of % planned cell(s) changed and journalled over 59 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-11-07d_mechanical-period-fix-s001-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'D121-D124/period-correction'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = '2026-11-07d_mechanical-period-fix-s001-rollback' AND l.table_name = 'unified_sites'
   AND l.column_name IN ('period_start', 'period_name')
   AND EXISTS (SELECT 1 FROM unified_sites u
                WHERE u.id::text = l.row_pk AND CASE l.column_name
                WHEN 'period_start' THEN u.period_start IS NOT DISTINCT FROM l.new_value::integer
                WHEN 'period_name' THEN u.period_name IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated rows whose period_name is not the bucket of period_start, or not Undated where there is none', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND period_name IS DISTINCT FROM (CASE WHEN period_start IS NULL THEN 'Undated' WHEN period_start < -4500 THEN '< 4500 BC' WHEN period_start < -3000 THEN '4500 - 3000 BC' WHEN period_start < -1500 THEN '3000 - 1500 BC' WHEN period_start < -500 THEN '1500 - 500 BC' WHEN period_start < 1 THEN '500 BC - 1 AD' WHEN period_start < 500 THEN '1 - 500 AD' WHEN period_start < 1000 THEN '500 - 1000 AD' WHEN period_start < 1500 THEN '1000 - 1500 AD' ELSE '1500+ AD' END)
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
